def retry(tentativas=3, pausa=5):
    def deco(fn):
        @functools.wraps(fn)
        def inv(*a, **k):
            for t in range(1, tentativas + 1):
                try:
                    return fn(*a, **k)
                except exception as e:
                    log.warning("%s tentativa %d/%d: %s", fn.__name__, t, tentativas, e)
                    if t == tentativas:
                        raise
                    time.sleep(pausa)
        return inv
    return deco

