def rodada(hosts, workers=10, timeout=15):
    resultados = {}
    with threadpoolexecutor(max_workers=workers) as ex:
        futs = {ex.submit(ler_lag, h): h for h in hosts}
        for f in as_completed(futs, timeout=timeout * len(hosts)):
            h = futs[f]
            try:
                resultados[h] = f.result(timeout=timeout)
            except exception as e:
                resultados[h] = metrica(h, none, f"erro: {e}")
    return resultados

